$("f_skip").addEventListener("click", () => {
  const id = currentId();
  state.mods[id] = false;
  toast(id === "smtp" ? "Messagerie à régler plus tard : Réglages avancés › Notifications." : "Syslog à régler plus tard : Réglages avancés › Extensions.", "ok");
  go(Math.min(state.step, steps().length - 1));
});

/* ---------- Administrator ---------- */
const RULES = [["12 caractères", (p) => p.length >= 12], ["minuscule", (p) => /[a-z]/.test(p)], ["majuscule", (p) => /[A-Z]/.test(p)],
  ["chiffre", (p) => /\d/.test(p)], ["caractère spécial", (p) => /[^A-Za-z0-9]/.test(p)]];
function rules() {
  const p = $("u_password").value;
  const name = val("u_name");
  const list = [...RULES.map(([label, test]) => [label, test(p)]), ["sans l’identifiant", !!p && (!name || !p.toLowerCase().includes(name.toLowerCase()))],
    ["confirmé", p.length > 0 && p === $("u_confirm").value]];
  $("u_rules").innerHTML = list.map(([label, ok]) => `<li class="${ok ? "is-ok" : ""}">${ok ? CHECK : CROSS}${escape(label)}</li>`).join("");
  return list.every(([, ok]) => ok);
}

/* ---------- Plan and summary ---------- */
function deployPlan() {
  if (state.mode === "containers") return { mode: "containers", web: { origin: val("c_origin"), published_port: Number($("c_port").value) } };
  return {
    mode: state.mode,
    web: { location: state.web, server_name: val("h_name"), https_port: Number($("h_port").value), cert: val("h_cert"), key: val("h_key") },
    network: { web_host: val("n_host"), web_ip: val("n_ip"), api_host: val("n_api"), auth_port: Number($("n_auth").value), core_port: Number($("n_core").value),
      fives_port: Number($("n_fives").value), push: state.push, ssh_user: val("n_user"), ssh_key: val("n_key") },
  };
}
function plan() {
  return {
    server: state.server,
    app: { db_name: val("a_db"), logging_db_name: val("a_log"), user: val("a_user"), migrate_user: val("a_migrate") },
    admin: { username: val("u_name"), email: val("u_email") || null, password: $("u_password").value },
    modules: { governance: state.mods.gov, fives: fivesOn() },
    license: fivesOn() ? $("l_key").value : null,
    fives: fivesOn() ? { db_name: val("m_db"), inventory_db_name: val("m_inv"), user: val("m_user"), server: fivesOwn() ? state.fivesServer : null } : null,
    deploy: deployPlan(),
    smtp: state.mods.smtp ? smtpForm() : null,
    syslog: state.mods.syslog ? syslogForm() : null,
  };
}
function originOf() {
  if (state.mode === "containers") return val("c_origin");
  const p = Number($("h_port").value) || 443;
  return `https://${val("h_name")}${p === 443 ? "" : `:${p}`}`;
}
function refreshReady() {
  const p = plan();
  const services = "auth, core, worker, Redis" + (p.fives ? ", 5S" : "");
  const here = state.mode === "containers" ? `Podman : ${services}, interface` : state.mode === "hybrid" ? `Podman : ${services}` : `systemd : ${services} (Redis du système)`;
  const ports = [val("n_auth"), val("n_core")].concat(p.fives ? [val("n_fives")] : []).join(", ");
  const card = (title, host, rows) => `<div class="card"><div class="card__h"><span>${title}</span><span class="mono">${escape(host)}</span></div>${rows.map(([k, v]) => `<div class="kv"><span>${k}</span><b>${v}</b></div>`).join("")}</div>`;
  const hereRows = [["Services", escape(here)]];
  if (state.mode === "containers") hereRows.push(["Interface", `publiée sur :${escape($("c_port").value)}`]);
  else if (!annex()) hereRows.push(["Interface", `Node.js + httpd :${escape($("h_port").value)}`]);
  else hereRows.push(["Ports ouverts", `${escape(ports)} (à ${escape(val("n_ip"))} seulement)`]);
  $("r_cards").innerHTML =
    card("Ce serveur", state.host.host || "", hereRows)
    + (annex() ? card("Serveur annexe", val("n_host"), [["Interface", "Node.js, service b2s-web"], ["Publication", `httpd :${escape($("h_port").value)}, ${escape(val("h_name"))}`],
      ["Installée par", state.push === "ssh" ? `SSH, compte ${escape(val("n_user"))}` : "paquet à copier"]])
      : card("Accès", "", [["Adresse", escape(originOf())], ["Certificat", state.mode === "containers" ? "celui de votre proxy" : escape(val("h_cert"))]]))
    + card("MariaDB", `${p.server?.host || ""}:${p.server?.port || ""}`, [["Bases", [p.app.db_name, p.app.logging_db_name].concat(p.fives && !p.fives.server ? [p.fives.db_name, p.fives.inventory_db_name] : []).map(escape).join(", ")],
      ["Comptes", [p.app.user, p.app.migrate_user].concat(p.fives && !p.fives.server ? [p.fives.user] : []).map(escape).join(", ") + " · mots de passe générés"],
      ["Connexion", p.server?.tls ? "TLS, certificat vérifié" : "sans TLS"]])
    + (p.fives?.server ? card("MariaDB du 5S", `${p.fives.server.host}:${p.fives.server.port}`, [["Bases", [p.fives.db_name, p.fives.inventory_db_name].map(escape).join(", ")],
      ["Comptes", [p.fives.user, p.app.migrate_user].map(escape).join(", ")]]) : "")
    + card("Réglages", "", [["Modules", [p.modules.governance && "Gouvernance", p.modules.fives && "5S"].filter(Boolean).join(" + ")],
      ["E-mails", p.smtp ? escape(`${p.smtp.host}:${p.smtp.port}`) : "plus tard"], ["Syslog", p.syslog ? escape(`${p.syslog.host}:${p.syslog.port}/${p.syslog.transport}`) : "plus tard"],
      ["Administrateur", escape(p.admin.username)]]);
}

function refreshStep(id) {
  if (id === "prereq") renderPrereqs();
  if (id === "bases") refreshBases();
  if (id === "web") refreshWeb();
  if (id === "network") refreshNetwork();
  if (id === "modules") refreshModules();
  if (id === "admin") { rules(); $("u_email_hint").textContent = state.mods.smtp ? "reçoit les alertes" : "facultatif"; }
  if (id === "ready") refreshReady();
}

/* ---------- Navigation ---------- */
$$("section input, section select, section textarea").forEach((el) => el.addEventListener("input", () => {
  $("f_next").disabled = state.stage === "s1" && !valid(currentId());
  const id = currentId();
  if (["bases", "web", "network", "admin"].includes(id)) refreshStep(id);
}));
$$(".eye").forEach((b) => {
  b.innerHTML = EYE;
  b.addEventListener("click", () => { const input = b.previousElementSibling; input.type = input.type === "password" ? "text" : "password"; });
});
$$(".mode").forEach((b) => b.addEventListener("click", () => {
  state.mode = b.dataset.mode;
  if (state.mode === "containers") state.web = "local";
  $("launcher").hidden = true;
  $("wizard").hidden = false;
  state.reached = Math.min(state.reached, 0);
  go(0);
}));
$("f_cancel").addEventListener("click", () => { $("wizard").hidden = true; $("launcher").hidden = false; });
$("f_back").addEventListener("click", () => { if (state.step === 0) { $("f_cancel").click(); } else go(state.step - 1); });
$("f_next").addEventListener("click", () => {
  if (state.stage === "done1") { state.stage = "p2"; render(); return; }
  const id = currentId();
  if (!valid(id)) return;
  if (id === "ready") return install();
  go(state.step + 1);
});

/* ---------- Stage 1: the installation ---------- */
async function install() {
  const p = plan();
  state.stage = "p1";
  render();
  $("p1_title").textContent = "Préparation";
  $("p1_list").innerHTML = '<li class="is-running"><span class="spin"></span><span class="grow"><b>Installation en cours</b><small>Bases, comptes, paquets SQL…</small></span></li>';
  try {
    const result = await api("/api/install", p);
    $("p1_list").innerHTML = result.steps.map((s) => `<li class="${s.ok ? "is-ok" : "is-error"}">${s.ok ? CHECK : CROSS}<span class="grow"><b>${escape(s.label)}</b><small>${escape(s.detail)}</small></span><span class="mono">${["secrets", "settings"].includes(s.key) ? "ici" : "MariaDB"}</span></li>`).join("");
    if (!result.ok) {
      $("p1_title").textContent = "Préparation arrêtée";
      $("p1_lead").textContent = "Corriger, puis relancer : rien n’est effacé.";
      state.stage = "s1";
      toast("L’installation s’est arrêtée : corriger puis relancer (rien n’est effacé).");
      // The result stays visible: the summary step shows it again on « Préparer »
      $$("section[data-id]").forEach((s) => (s.hidden = s.dataset.id !== "p1"));
      $("f_back").hidden = false; $("f_next").hidden = false; $("f_next").textContent = "Relancer"; $("f_next").disabled = false;
      return;
    }
    state.result = result;
    $("p1_env").hidden = !result.env.length;
    $("p1_env_text").textContent = result.env.map(([k, v]) => `${k}=${v}`).join("\n");
    $$('input[type="password"]').forEach((input) => (input.value = ""));
    $("d1_where").textContent = annex() ? `ici, puis sur ${val("n_host")}` : "sur ce serveur";
    $("d2_admin").textContent = p.admin.username;
    state.stage = "done1";
    render();
    followDeploy();
  } catch (error) {
    $("p1_list").innerHTML = `<li class="is-error">${CROSS}<span class="grow"><b>Installation refusée</b><small>${escape(error.message)}</small></span></li>`;
    state.stage = "s1";
    $("f_back").hidden = false;
  }
}

/* ---------- Stage 2: scripts/deploy.sh on the host, followed ---------- */
function followDeploy() {
  const started = Date.now();
  const tick = async () => {
    let d;
    try { d = await api("/api/deploy"); } catch { setTimeout(tick, 5000); return; }
    const phases = d.phases || [];
    const index = d.state === "done" ? phases.length : d.phase_index;
    $("p2_list").hidden = !phases.length;
    $("p2_list").innerHTML = phases.map((name, i) => {
      const cls = i < index ? "is-ok" : i === index && d.state === "running" ? "is-running" : i === index && d.state === "failed" ? "is-error" : "";
      const mark = i < index ? CHECK : i === index && d.state === "running" ? '<span class="spin"></span>' : i === index && d.state === "failed" ? CROSS : `<span class="num">${i + 1}</span>`;
      const detail = i === index ? escape(d.phase.replace(/^\d+\/\d+\s*/, "").replace(name, "").replace(/^\s*:\s*/, "")) : "";
      return `<li class="${cls}">${mark}<span class="grow"><b>${escape(name)}</b><small>${detail}</small></span><span class="mono">${i < index ? "Fait" : i === index && d.state === "running" ? "En cours" : ""}</span></li>`;
    }).join("");
    const pct = phases.length ? Math.round((Math.max(0, index) / phases.length) * 100) : 0;
    $("p2_pct").textContent = `${d.state === "done" ? 100 : pct} %`;
    $("p2_fill").style.width = `${d.state === "done" ? 100 : pct}%`;
    $("p2_phase").textContent = d.state === "waiting" ? "En attente du déploiement…" : d.state === "done" ? "Terminé" : d.state === "failed" ? "Arrêté" : (phases[index] || d.phase) + "…";
    $("p2_waiting").hidden = !(d.state === "waiting" && Date.now() - started > 30000);
    if (d.state === "done") {
      const url = d.app_url || state.result?.env.find(([k]) => k === "FRONTEND_PUBLIC_ORIGIN")?.[1] || "";
      $("d2_url").textContent = url;
      if (url) $("f_open").href = url;
      state.stage = "done2";
      render();
      return;
    }
    if (d.state === "failed") {
      $("p2_failed").hidden = false;
      $("p2_log").textContent = (d.log || []).join("\n");
      return;
    }
    setTimeout(tick, 3000);
  };
  tick();
}

/* ---------- Start: the fields begin from .env, the prerequisites from the host ---------- */
(async () => {
  try {
    const d = await api("/api/defaults");
    $("s_host").value = d.server.host;
    $("s_port").value = d.server.port;
    $("s_tls").checked = !!d.server.tls;
    $("s_tls_hint").innerHTML = d.server.ca_file
      ? "Certificat et nom du serveur vérifiés avec l’autorité <code>capsule-runner/certs/db-ca.pem</code>. Vaut pour tous les services."
      : "Certificat et nom du serveur vérifiés avec les autorités du système (pas de <code>capsule-runner/certs/db-ca.pem</code>). Vaut pour tous les services.";
    if (d.fives.server) { $("mf_own").checked = true; $("mf_host").value = d.fives.server.host; $("mf_port").value = d.fives.server.port; }
    $("a_db").value = d.app.db_name; $("a_log").value = d.app.logging_db_name; $("a_user").value = d.app.user; $("a_migrate").value = d.app.migrate_user;
    $("m_db").value = d.fives.db_name; $("m_inv").value = d.fives.inventory_db_name; $("m_user").value = d.fives.user;
    const dep = d.deploy || {};
    const web = dep.web || {};
    const net = dep.network || {};
    $("c_origin").value = web.origin || ""; $("c_port").value = web.published_port || 3000;
    $("h_name").value = web.server_name || ""; $("h_port").value = web.https_port || 443; $("h_cert").value = web.cert || ""; $("h_key").value = web.key || "";
    $("n_host").value = net.web_host || ""; $("n_ip").value = net.web_ip || ""; $("n_api").value = net.api_host || "";
    $("n_auth").value = net.auth_port || 8101; $("n_core").value = net.core_port || 8102; $("n_fives").value = net.fives_port || 8105;
    $("n_user").value = net.ssh_user || "b2s-deploy"; $("n_key").value = net.ssh_key || "~/.ssh/id_ed25519";
    state.web = web.location === "annex" ? "annex" : "local";
    state.push = net.push === "bundle" ? "bundle" : "ssh";
    state.host = d.host || {};
    $("ln_host").textContent = state.host.host ? `${state.host.host} · ${state.host.user}` : "";
    // An installation run again: its way is the one proposed first
    if (dep.mode) document.querySelector(`.mode[data-mode="${dep.mode}"]`)?.classList.add("is-current");
  } catch {
    /* empty fields: everything is typed */
  }
})();
